private Task EnsureClientOwnedSystemFilesHealthyAsync(bool ordinaryEntry = false)=>
    SessionOperationContext.RunParticipatingCurrentSessionAsync(_fs,()=>EnsureClientOwnedSystemFilesHealthyCoreAsync(ordinaryEntry));
private async Task EnsureClientOwnedSystemFilesHealthyCoreAsync(bool ordinaryEntry)
{
    await CleanupOrphanedTurnRequestBeforeValidationAsync();
    await _stateManager.RefreshGameStateAsync();
    var preserveControlFilesForTerminalValidation =
        await ShouldPreserveClientOwnedControlFilesForTerminalValidationAsync();

    if (ordinaryEntry)
    {
        if (!await WriteGameSettingsForGm())
            throw new InvalidDataException("Синхронизация настроек не подтверждена. Требуется завершить активную запись или восстановление перед продолжением.");
    }
    else
    {
        // B3: accepted-turn/repair receipt workflows retain their existing
        // route until that whole publication boundary is migrated.
        if (await _systemModService.WriteManifestForGmAsync())
            await _stateManager.SaveSettingsAsync();
    }

    await AfterlifeNotificationState.EnsureHealthyAsync(_fs);
    if (!preserveControlFilesForTerminalValidation)
    {
        await _afterlifeReturnGuardService.EnsureHealthyAsync(_stateManager.CurrentState.CurrentRealm);
        await _systemGuardianLibraryService.EnsureAttractionRequestHealthyAsync(_stateManager.CurrentState.CurrentRealm);
    }

    await _qteSceneService.EnsureRuntimeStateHealthyAsync();
    await _progressionSchedule.EnsureInitializedAsync();
}

private async Task CleanupOrphanedTurnRequestBeforeValidationAsync()
{
    if (!_fs.FileExists("input/turn_request.json"))
        return;

    if (HasTerminalReadySignal() ||
        _fs.FileExists(ValidationRepairRequestPath) ||
        _fs.FileExists(ValidationRepairReadyPath))
        return;

    var pendingSnapshot = await ResolveActivePendingTurnSnapshotContextAsync();
    if (pendingSnapshot.Status == PendingTurnSnapshotResolutionStatus.Usable)
        return;

    _logger.LogWarning(
        pendingSnapshot.Status == PendingTurnSnapshotResolutionStatus.Missing
            ? "Найден orphaned input/turn_request.json без pending snapshot manifest перед validation. Удаление как stale runtime artifact."
            : "Найден input/turn_request.json с unreadable/invalid validated pending snapshot authority перед validation. Удаление как stale runtime artifact.");
    _fs.DeleteFile("input/turn_request.json");
}

if (errors.Count == 0)
{
    if (allowRepairLoop && lastRepairErrors is { Count: > 0 })
    {
        await AppendClearedValidationRepairTrajectoryAsync(
            source,
            lastRepairErrors,
            lastRepairAttempt,
            lastRepairSessionGeneration!);
        await DeleteValidationRepairFilesForSessionAsync(lastRepairSessionGeneration!);
    }
    else
    {
        await DeleteValidationRepairFilesAsync();
    }
    if (applyProgressionOnSuccess && progressionControl != null)
        await _progressionSchedule.ApplyAcceptedTurnOutcomeAsync(progressionControl);

private async Task DeleteValidationRepairFilesAsync()
{
    var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    CoordinatedStatePublicationUncertainException? uncertainty = null;
    try
    {
        DeleteValidationRepairFiles(writeLease);
    }
    catch (CoordinatedStatePublicationUncertainException failure)
    {
        uncertainty = failure;
        throw;
    }
    finally
    {
        await CoordinatedStateWriteHelper.ReleaseOwnedLeaseAsync(_fs, writeLease, false, uncertainty);
    }

}

private async Task DeleteValidationRepairFilesForSessionAsync(string expectedSessionGeneration)
{
    var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    Exception? publicationUncertainty = null;
    try
    {
        ThrowIfRepairSessionReplaced(writeLease, expectedSessionGeneration);
        DeleteValidationRepairFiles(writeLease);
    }
    catch (CoordinatedStatePublicationUncertainException failure)
    {
        publicationUncertainty = failure;
        throw;
    }
    finally
    {
        await CoordinatedStateWriteHelper.ReleaseOwnedLeaseAsync(
            _fs, writeLease, completed: false, operationFailure: publicationUncertainty);
    }
}

private void DeleteValidationRepairFiles(FileSystemManager.CanonicalWriteLease writeLease)
{
    _fs.DeleteFile(writeLease, ValidationRepairReadyPath);
    _fs.DeleteFile(writeLease, ValidationRepairRequestPath);
    _fs.DeleteFile(writeLease, ValidationRepairArtifactStallReportPath);
}

private async Task WriteValidationRepairFileForSessionAsync(
    string relativePath,
    string content,
    string expectedSessionGeneration)
{
    var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    CoordinatedStatePublicationUncertainException? uncertainty = null;
    try
    {
        ThrowIfRepairSessionReplaced(writeLease, expectedSessionGeneration);
        await _fs.WriteFileAtomicAsync(writeLease, relativePath, content);
    }
    catch (CoordinatedStatePublicationUncertainException failure) { uncertainty = failure; throw; }
    finally { await CoordinatedStateWriteHelper.ReleaseOwnedLeaseAsync(_fs, writeLease, false, uncertainty); }
}

private async Task<string?> ReadValidationRepairFileForSessionAsync(
    string relativePath,
    string expectedSessionGeneration)
{
    await using var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    ThrowIfRepairSessionReplaced(writeLease, expectedSessionGeneration);
    return await _fs.ReadFileAsync(writeLease, relativePath);
}

private void ThrowIfRepairSessionReplaced(
    FileSystemManager.CanonicalWriteLease writeLease,
    string expectedSessionGeneration)
{
    if (!_fs.IsCurrentSessionGeneration(writeLease, expectedSessionGeneration))
    {
        throw new GmWorkerSessionReplacedException(
            "The validation-repair cycle belongs to a game session that is no longer current.");
    }

private async Task<ValidationRepairDispatchState> WriteValidationRepairRequestAsync(
    string source,
    List<ValidationIssue> errors,
    int attempt)
{
    var sessionGeneration = await CaptureCurrentSessionGenerationAsync();
    return await WriteValidationRepairRequestForSessionAsync(
        source,
        errors,
        attempt,
        sessionGeneration);
}

private async Task<ValidationRepairDispatchState> WriteValidationRepairRequestForSessionAsync(
    string source,
    List<ValidationIssue> errors,
    int attempt,
    string expectedSessionGeneration,
    IReadOnlyList<MortalLocationRepairRetryObligation>? mortalLocationRetryObligations = null,
    IReadOnlyList<RepairResubmissionPathObligation>? mortalLocationRequiredResubmissionPaths = null,
    IReadOnlyList<EffectRepairRetryObligation>? effectRetryObligations = null,
    IReadOnlyList<RepairResubmissionPathObligation>? effectRequiredResubmissionPaths = null,
    IReadOnlyList<ResourceRepairRetryObligation>? resourceRetryObligations = null,
    IReadOnlyList<RepairResubmissionPathObligation>? resourceRequiredResubmissionPaths = null,
    IReadOnlyList<WoundRepairRetryObligation>? woundRepairRetryObligations = null,
    IReadOnlyList<RepairResubmissionPathObligation>? woundRequiredResubmissionPaths = null,
    IReadOnlyList<EffectRepairPacket>? effectRepairPackets = null,
    bool boundedPendingResolutionResubmission = false)
{
    await DeleteValidationRepairFilesForSessionAsync(expectedSessionGeneration);
    var prioritizedErrors = PrioritizeValidationErrors(errors).ToList();
    var pendingSnapshot = await ResolveActivePendingTurnSnapshotContextAsync();
    var requestMetadata = BuildProtocolRequestMetadata(pendingSnapshot);
    var metadataDiagnosticOnly = BuildProtocolRequestMetadataDiagnosticOnly(pendingSnapshot);
    var resourceRepairPackets = ResourceRepairPacketBuilder.Build(prioritizedErrors);
    var fullTurnResubmissionRequired =
        boundedPendingResolutionResubmission ||
        mortalLocationRetryObligations is { Count: > 0 } ||
        effectRetryObligations is { Count: > 0 } ||
        effectRepairPackets is { Count: > 0 } ||
        woundRepairRetryObligations is { Count: > 0 } ||
        resourceRepairPackets.Count > 0;
    var woundRepairPackets = WoundRepairPacketBuilder.Build(prioritizedErrors);
    fullTurnResubmissionRequired =
        fullTurnResubmissionRequired || woundRepairPackets.Count > 0;
    var gmInstructions = BuildValidationRepairRequestInstructions(
        pendingSnapshot,
        fullTurnResubmissionRequired,
        boundedPendingResolutionResubmission);

    var request = new ValidationRepairRequest
    {
        SessionId = requestMetadata.SessionId,
        RequestId = requestMetadata.RequestId,
        TurnNumber = requestMetadata.TurnNumber,
        MetadataDiagnosticOnly = metadataDiagnosticOnly,
        Source = source,
        DetectedAtUtc = DateTime.UtcNow.ToString("o"),
        RevalidationAttempt = attempt,
        FullTurnResubmissionRequired = fullTurnResubmissionRequired,
        GmInstructions = gmInstructions,
        SummaryGroups = BuildValidationSummaryLines(prioritizedErrors, 6),
        HarnessRepairPackets = BuildValidationRepairHarnessPackets(
            prioritizedErrors,
            await ReadCurrentGuardianRepairActorNameHintsAsync(),
            effectRepairPackets),
        ResubmissionObligations = (mortalLocationRetryObligations?
            .Select(obligation => new ValidationRepairResubmissionObligation
            {
                Actor = obligation.Actor,
                Route = obligation.Route,
                RawCarrier = obligation.Route is "current_scene_creation" or "current_selection"
                    ? "currentLocationData"
                    : "worldMapUpdates"
            }) ?? Enumerable.Empty<ValidationRepairResubmissionObligation>())
            .Concat(effectRetryObligations?
                .Select(obligation => new ValidationRepairResubmissionObligation
                {
                    Actor = obligation.Actor,
                    Route = "effectChanges",
                    RawCarrier = EffectAcceptedTurnPlan.CommandPath
                }) ?? Enumerable.Empty<ValidationRepairResubmissionObligation>())
            .Concat(resourceRetryObligations?
                .Select(obligation => new ValidationRepairResubmissionObligation
                {
                    Actor = $"ordinary resource change #{obligation.CommandOrdinal + 1}",
                    Route = "resourceChanges",
                    RawCarrier = "accepted turn response"
                }) ?? Enumerable.Empty<ValidationRepairResubmissionObligation>())
            .Concat((woundRepairRetryObligations?
                    .Select(static obligation => obligation.Packet) ??
                woundRepairPackets).Select(packet =>
                new ValidationRepairResubmissionObligation
                {
                    Actor = packet.CandidateRef,
                    Route = packet.ResubmissionRoute,
                    RawCarrier = "accepted turn response"
                }))
            .ToList(),
        RequiredResubmissionPaths = (mortalLocationRequiredResubmissionPaths ??
                Array.Empty<RepairResubmissionPathObligation>())
            .Concat(effectRequiredResubmissionPaths ??
                    Array.Empty<RepairResubmissionPathObligation>())
            .Concat(resourceRequiredResubmissionPaths ??
                    Array.Empty<RepairResubmissionPathObligation>())
            .Concat(woundRequiredResubmissionPaths ??
                    Array.Empty<RepairResubmissionPathObligation>())
            .Select(static obligation => obligation.Path)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
            .ToList(),
        Errors = prioritizedErrors.Select(e => new ValidationRepairIssue
        {
            Code = e.Code ?? "validation_error",
            FilePath = e.FilePath,
            Severity = e.Severity.ToString(),
            Category = e.Category.ToString(),
            Message = e.Message,
            Actor = e.Actor,
            Section = e.Section,
            Expected = e.Expected,
            Actual = e.Actual,
            RepairHint = e.RepairHint ?? "Исправь состояние/структуру так, чтобы оно соответствовало Rules/API contract."
        }).ToList()
    };

    PublishAgentConsoleValidationRepairSnapshot();
    GmWorkerValidationRepairDispatchResult? workerResult = null;
    if (!metadataDiagnosticOnly && !fullTurnResubmissionRequired)
    {
        workerResult = await RunWorkerValidationRepairIfAvailableAsync(
            prioritizedErrors,
            requestMetadata,
            request.DetectedAtUtc,
            attempt,
            expectedSessionGeneration);
        if (workerResult.Outcome == GmWorkerValidationRepairOutcome.Applied)
        {
            return new ValidationRepairDispatchState
            {
                WorkerApplyAccepted = true,
                ReadySignalCreated = workerResult.ReadySignalCreated,
                WorkerResult = workerResult
            };
        }
        if (workerResult.Outcome == GmWorkerValidationRepairOutcome.SessionReplaced)
        {
            return new ValidationRepairDispatchState
            {
                SessionReplaced = true,
                WorkerResult = workerResult
            };
        }
    }

    await WriteValidationRepairFileForSessionAsync(
        ValidationRepairRequestPath,
        JsonSerializer.Serialize(request, JsonOpts),
        expectedSessionGeneration);
    return new ValidationRepairDispatchState
    {
        MetadataDiagnosticOnly = metadataDiagnosticOnly,
        WorkerResult = workerResult
    };
}

private sealed class ValidationRepairRequest
{
    public string SessionId { get; set; } = "";
    public string RequestId { get; set; } = "";
    public int TurnNumber { get; set; }
    public bool MetadataDiagnosticOnly { get; set; }
    public string Source { get; set; } = "";
    public string DetectedAtUtc { get; set; } = "";
    public int RevalidationAttempt { get; set; }
    public bool FullTurnResubmissionRequired { get; set; }
    /// <summary>
    /// Carries the current owner-derived continuation, or is omitted for ordinary repair.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public SpiritualWoundContinuationRequest? SpiritualWoundContinuation { get; set; }
    public string GmInstructions { get; set; } = "";
    public List<string> SummaryGroups { get; set; } = new();
    public List<JsonObject> HarnessRepairPackets { get; set; } = new();
    public List<ValidationRepairResubmissionObligation> ResubmissionObligations { get; set; } = new();
    public List<string> RequiredResubmissionPaths { get; set; } = new();
    public List<ValidationRepairIssue> Errors { get; set; } = new();
}

private async Task<string[]> BuildValidationRepairTrajectoryRepairPacketRefsAsync(IEnumerable<ValidationIssue> errors)
{
    var refs = new List<string>();

    if (_fs.FileExists(ValidationRepairRequestPath))
    {
        try
        {
            var json = await _fs.ReadFileAsync(ValidationRepairRequestPath);
            var request = string.IsNullOrWhiteSpace(json)
                ? null
                : JsonSerializer.Deserialize<ValidationRepairRequest>(json, JsonOpts);

            if (request?.HarnessRepairPackets is { Count: > 0 })
            {
                refs.AddRange(request.HarnessRepairPackets
                    .Select(ReadValidationRepairPacketKind)
                    .Where(kind => !string.IsNullOrWhiteSpace(kind))!);
            }
        }
        catch (Exception ex)
        {
            _logger.LogWarning(
                ex,
                "Failed to read validation repair packet refs from active repair request for trajectory ledger.");
        }
    }

    if (refs.Count == 0)
    {
        refs.AddRange(BuildValidationRepairHarnessPackets(
                PrioritizeValidationErrors(errors).ToList(),
                await ReadCurrentGuardianRepairActorNameHintsAsync())
            .Select(ReadValidationRepairPacketKind)
            .Where(kind => !string.IsNullOrWhiteSpace(kind))!);
    }

    return refs
        .Distinct(StringComparer.OrdinalIgnoreCase)
        .OrderBy(reference => reference, StringComparer.OrdinalIgnoreCase)
        .ToArray();
}

private async Task NormalizePendingRepairArtifactsAsync()
{
    await SessionOperationContext.RunParticipatingCurrentSessionAsync(_fs, NormalizePendingRepairArtifactsCoreAsync);
}

private async Task NormalizePendingRepairArtifactsCoreAsync()
{
    var repairRequestExists = _fs.FileExists(ValidationRepairRequestPath);
    var repairReadyExists = _fs.FileExists(ValidationRepairReadyPath);
    if (!repairRequestExists && !repairReadyExists)
        return;

    var pendingSnapshot = await ResolveActivePendingTurnSnapshotContextAsync();
    if (pendingSnapshot.Status == PendingTurnSnapshotResolutionStatus.Missing)
    {
        _logger.LogWarning("Найдены repair-файлы без pending snapshot manifest. Очистка как stale state.");
        await DeleteValidationRepairFilesAsync();
        return;
    }

    if (pendingSnapshot.Status != PendingTurnSnapshotResolutionStatus.Usable || pendingSnapshot.Context == null)
    {
        _logger.LogWarning("Найдены repair-файлы с unreadable/invalid validated pending snapshot authority. Очистка как stale state.");
        await DeleteValidationRepairFilesAsync();
        return;
    }

    var snapshotContext = pendingSnapshot.Context;

    if (repairRequestExists && await TryPromoteValidationRepairArtifactStallToTerminalErrorAsync(snapshotContext))
        return;

    if (repairReadyExists && !repairRequestExists)
    {
        _logger.LogWarning(
            "Найден orphaned validation_repair_ready для pending turn(session={Session}, request={Request}, turn={Turn}). Удаление ready-файла без затрагивания основного pending turn state.",
            snapshotContext.SessionId,
            snapshotContext.RequestId,
            snapshotContext.TurnNumber);
        await DeleteValidationRepairReadyAsync();
        return;
    }

    if (repairRequestExists)
    {
        if (!_fs.FileExists("ready/turn_complete.json"))
        {
            _logger.LogWarning(
                "Найден validation_repair_request без correlated ready/turn_complete.json для pending turn(session={Session}, request={Request}, turn={Turn}). Очистка stale repair artifacts.",
                snapshotContext.SessionId,
                snapshotContext.RequestId,
                snapshotContext.TurnNumber);
            await DeleteValidationRepairFilesAsync();
            return;
        }

        var turnCompleteMetadata = await ReadReadySignalMetadataAsync("ready/turn_complete.json");
        if (turnCompleteMetadata == null ||
            !string.Equals(turnCompleteMetadata.SessionId, snapshotContext.SessionId, StringComparison.Ordinal) ||
            !string.Equals(turnCompleteMetadata.RequestId, snapshotContext.RequestId, StringComparison.Ordinal) ||
            turnCompleteMetadata.TurnNumber != snapshotContext.TurnNumber)
        {
            _logger.LogWarning(
                "Найден validation_repair_request с некоррелированным ready/turn_complete.json. Очистка stale repair artifacts для pending turn(session={Session}, request={Request}, turn={Turn}).",
                snapshotContext.SessionId,
                snapshotContext.RequestId,
                snapshotContext.TurnNumber);
            _fs.DeleteFile("ready/turn_complete.json");
            await DeleteValidationRepairFilesAsync();
            return;
        }

        _logger.LogInformation(
            "Обнаружен активный repair cycle для pending turn(session={Session}, request={Request}, turn={Turn}). Он будет продолжен через correlated late-response validation.",
            snapshotContext.SessionId,
            snapshotContext.RequestId,

private async Task<bool> TryPromoteValidationRepairArtifactStallToTerminalErrorAsync(
    ValidatedPendingTurnSnapshotContext snapshotContext,
    string? expectedSessionGeneration = null)
{
    var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    CoordinatedStatePublicationUncertainException? owningPublicationUncertainty = null;
    try
    {
        if (!string.IsNullOrWhiteSpace(expectedSessionGeneration))
            ThrowIfRepairSessionReplaced(writeLease, expectedSessionGeneration);

        if (!_fs.FileExists(writeLease, ValidationRepairArtifactStallReportPath) ||
            _fs.FileExists(writeLease, "ready/turn_error.json") ||
            !_fs.FileExists(writeLease, ValidationRepairRequestPath))
        {
            return false;
        }

        var requestJson = await _fs.ReadFileAsync(writeLease, ValidationRepairRequestPath);
        if (string.IsNullOrWhiteSpace(requestJson))
            return false;

        ValidationRepairRequest? repairRequest;
        try
        {
            repairRequest = JsonSerializer.Deserialize<ValidationRepairRequest>(requestJson, JsonOpts);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Найден validation repair artifact stall report, но validation_repair_request.json не читается.");
            return false;
        }

        if (repairRequest == null ||
            !string.Equals(repairRequest.SessionId, snapshotContext.SessionId, StringComparison.Ordinal) ||
            !string.Equals(repairRequest.RequestId, snapshotContext.RequestId, StringComparison.Ordinal) ||
            repairRequest.TurnNumber != snapshotContext.TurnNumber)
        {
            return false;
        }

        if (_fs.FileExists(writeLease, "ready/turn_complete.json"))
        {
            var completeMetadata = ParseReadySignalMetadata(
                await _fs.ReadFileAsync(writeLease, "ready/turn_complete.json"),
                "ready/turn_complete.json");
            if (completeMetadata == null ||
                !string.Equals(completeMetadata.SessionId, snapshotContext.SessionId, StringComparison.Ordinal) ||
                !string.Equals(completeMetadata.RequestId, snapshotContext.RequestId, StringComparison.Ordinal) ||
                completeMetadata.TurnNumber != snapshotContext.TurnNumber)
            {
                return false;
            }
        }

        JsonNode? stallReportNode = null;
        var stallReportJson = await _fs.ReadFileAsync(writeLease, ValidationRepairArtifactStallReportPath);
        if (!string.IsNullOrWhiteSpace(stallReportJson))
        {
            try
            {
                stallReportNode = JsonNode.Parse(stallReportJson);
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Найден validation repair artifact stall report, но report JSON не читается.");
            }
        }

        var signal = new JsonObject
        {
            ["sessionId"] = repairRequest.SessionId,
            ["requestId"] = repairRequest.RequestId,
            ["turnNumber"] = repairRequest.TurnNumber,
            ["timestamp"] = DateTimeOffset.UtcNow.ToString("O"),
            ["status"] = "error",
            ["harnessSource"] = "gm_validation_repair_artifact_stall",
            ["error"] = "Validation repair stalled without target artifact progress; GM bridge was stopped by harness cleanup."
        };

        if (stallReportNode != null)
            signal["validationRepairArtifactStall"] = stallReportNode;

        await _fs.WriteFileAtomicAsync(writeLease, "ready/turn_error.json", signal.ToJsonString(JsonOpts));
        _fs.DeleteFile(writeLease, "ready/turn_complete.json");
        _fs.DeleteFile(writeLease, ValidationRepairReadyPath);

        _logger.LogWarning(
            "Validation repair artifact stall promoted to terminal error for pending turn(session={Session}, request={Request}, turn={Turn}).",
            repairRequest.SessionId,
            repairRequest.RequestId,
            repairRequest.TurnNumber);
        return true;
    }
    catch (CoordinatedStatePublicationUncertainException failure) { owningPublicationUncertainty = failure; throw; }
    finally { await CoordinatedStateWriteHelper.ReleaseOwnedLeaseAsync(_fs, writeLease, false, owningPublicationUncertainty); }
}

private async Task NormalizePendingTerminalProtocolFailureArtifactsAsync()
{
    await SessionOperationContext.RunParticipatingCurrentSessionAsync(_fs, NormalizePendingTerminalProtocolFailureArtifactsCoreAsync);

private async Task<bool> IsCurrentPendingTurnSnapshotAsync(PendingTurnSnapshotManifest manifest)
{
    const string repairRequestPath = "game_state/control/validation_repair_request.json";
    var repairContext = await ReadPendingTurnSnapshotRequestContextAsync(repairRequestPath);
    if (DoesPendingTurnRequestContextMatchManifest(manifest, repairContext))
        return true;

    var turnContext = await ReadPendingTurnSnapshotRequestContextAsync("input/turn_request.json");
    if (DoesPendingTurnRequestContextMatchManifest(manifest, turnContext))
        return true;

    var completionContext = await ReadPendingTurnSnapshotRequestContextAsync("ready/turn_complete.json");
    return DoesPendingTurnRequestContextMatchManifest(manifest, completionContext);
}

private async Task<PendingTurnSnapshotRequestContext?> ReadPendingTurnSnapshotRequestContextAsync(string relativePath)
{
    var json = await _fs.ReadFileAsync(relativePath);
    if (string.IsNullOrWhiteSpace(json))
        return null;

    try
    {
        using var doc = JsonDocument.Parse(json);
        if (doc.RootElement.ValueKind != JsonValueKind.Object)
            return null;

        var sessionId = doc.RootElement.TryGetProperty("sessionId", out var sessionIdNode) &&
                        sessionIdNode.ValueKind == JsonValueKind.String
            ? sessionIdNode.GetString() ?? string.Empty
            : string.Empty;
        var requestId = doc.RootElement.TryGetProperty("requestId", out var requestIdNode) &&
                        requestIdNode.ValueKind == JsonValueKind.String
            ? requestIdNode.GetString() ?? string.Empty
            : string.Empty;
        var turnNumber = doc.RootElement.TryGetProperty("turnNumber", out var turnNumberNode) &&
                         turnNumberNode.ValueKind == JsonValueKind.Number &&
                         turnNumberNode.TryGetInt32(out var parsedTurnNumber)
            ? parsedTurnNumber
            : 0;

        return new PendingTurnSnapshotRequestContext(sessionId, requestId, turnNumber);
    }
    catch
    {
        return null;
    }
}

private static bool DoesPendingTurnRequestContextMatchManifest(
    PendingTurnSnapshotManifest manifest,
    PendingTurnSnapshotRequestContext? context)
{
    if (context == null)
        return false;

    if (manifest.TurnNumber != context.TurnNumber)
        return false;

    if (!PendingTurnSnapshotAuthority.DoesPendingTurnContextIdMatch(manifest.SessionId, context.SessionId))
        return false;

    return PendingTurnSnapshotAuthority.DoesPendingTurnContextIdMatch(manifest.RequestId, context.RequestId);

    new("game_state/control/validation_repair_request.json", IsRepairRequest: true),
    new(LiveTurnPreparationService.TurnRequestPath, IsRepairRequest: false),
    new("ready/turn_complete.json", IsRepairRequest: false)
};

internal static PendingTurnSnapshotReadResult ReadCurrent(
    FileSystemManager fs,
    FileSystemManager.CanonicalWriteLease lease,
    IReadOnlyCollection<string> requiredLogicalPaths) =>
    ReadCurrentCore(fs, lease, requiredLogicalPaths, null);

private static PendingTurnSnapshotReadResult ReadCurrentCore(
    FileSystemManager fs,
    FileSystemManager.CanonicalWriteLease lease,
    IReadOnlyCollection<string> requiredLogicalPaths,
    OriginalSourceReadSession? sourceSession)
{
    ArgumentNullException.ThrowIfNull(fs);
    ArgumentNullException.ThrowIfNull(lease);
    ArgumentNullException.ThrowIfNull(requiredLogicalPaths);
    fs.EnsureCanonicalWriteLeaseActive(lease);

    var issues = new List<ValidationIssue>();
    var selection = ValidatePathSelection(requiredLogicalPaths, issues);
    if (issues.Count != 0)
        return Failure(issues);

    if (sourceSession is not null && !sourceSession.Begin(issues))
        return Failure(issues);

    LiveTurnPendingSnapshotManifest? manifest;
    try
    {
        var manifestJson = sourceSession is null
            ? fs.ReadFileSync(LiveTurnPreparationService.PendingTurnSnapshotManifestPath)
            : sourceSession.ReadManifestText();
        if (string.IsNullOrWhiteSpace(manifestJson) || HasDuplicateJsonProperties(manifestJson))
        {
            manifest = null;
        }
        else
        {
            manifest = JsonSerializer.Deserialize<LiveTurnPendingSnapshotManifest>(
                manifestJson,
                LiveTurnPreparationService.ManifestJsonOptions);
        }
    }
    catch (JsonException)
    {
        manifest = null;
    }

    if (manifest is null || manifest.Files is null || manifest.SnapshotFileHashes is null)
    {
        Add(
            issues,
            LiveTurnPreparationService.PendingTurnSnapshotManifestPath,
            "pending_turn_snapshot_reader_manifest_invalid",
            "missing or malformed pending-turn manifest");
        return Failure(issues);
    }

    ValidateNoCaseConfusableCoverage(selection, manifest, issues);
    if (issues.Count != 0)
        return Failure(issues);

    var authorityJson = sourceSession is null
        ? fs.ReadFileSync(PendingTurnSnapshotAuthority.AuthorityPath)
