function New-GmPromptOperation {
    param([string]$Message, [string]$PendingPath = '', [string]$OperationKind = 'turn', [string]$OperationRevision = 'live', [string]$ExpectedSourceHash = '')
    $sourceHash = ''
    if ($PendingPath) {
