                    _trees[tree]=_trees[tree].Append(path).OrderBy(x=>x,_comparer).ToArray();
            foreach(var parent in _kinds.Keys.ToArray())
                if(IsDescendant(path,parent)) _kinds[parent]=TrustedLocalNamespaceKind.Directory;
